def evaluate_latency_test(p_value, alpha=0.05):
    if p_value < alpha:
        return "H0 is rejected: the models have different average latency."
    else:
        return "H0 is accepted: the models have the same average latency."

print(evaluate_latency_test(p_value=0.62))

