from scipy import stats

def two_sided_p_value(t_statistic, df):
    return 2 * stats.t.sf(abs(t_statistic), df)

p = two_sided_p_value(t_statistic=1.9, df=18)
print(f"{p:.4f}")   # 0.0736
print("Reject H0" if p < 0.05 else "Fail to reject H0")   # Fail to reject H0
